class TFMLogicStepOperatorClassifyAndReplaceInput extends TFMLogicBlock implements TFMLogicStepOperatorInterface
{
    TFMFlowVariableName variableName;
    TFMFlowContextField contextField;

}

Method.Source:
[TFMParameter('', "@TFM:Whichfieldtoclassifyandreplace")]
public TFMFlowContextField parmContextField(TFMFlowContextField _contextField = contextField)
{
    contextField = _contextField;
    return contextField;
}

public str runLogic ( TFMRequestElement _request )
{

    str                 fieldValue = _request.getFieldValue(contextField);
    str                 newValue = TFMClassificationHierarchy::findAndReplaceInput(fieldValue);
    _request.addField(contextField, newValue,true);

    return '';
}
